using TextKit.Core;

namespace TextKit.Commands;

public class UpperCommand : ICommand
{
    public string Name => "upper";
    public string Usage => "upper <file>";
    public string Description => "Print the file in upper case";

    public int Run(string[] args, TextWriter output)
    {
        if (args.Length != 1)
        {
            throw CommandException.Usage(this);
        }

        output.Write(InputFile.ReadAllText(args[0]).ToUpperInvariant());
        return ExitCodes.Ok;
    }
}

