using TextKit;
using TextKit.Commands;
using TextKit.Core;

namespace TextKit.Tests.Commands;

public class UpperCommandTests : IDisposable
{
    private readonly string directory = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));

    [Fact]
    public void PrintsUpperCaseWithoutAddingNewline()
    {
        Directory.CreateDirectory(directory);
        var path = Path.Combine(directory, "input.txt");
        File.WriteAllText(path, "hello\r\nworld", System.Text.Encoding.UTF8);
        using var output = new StringWriter { NewLine = "\n" };

        var result = new UpperCommand().Run([path], output);

        Assert.Equal(ExitCodes.Ok, result);
        Assert.Equal("HELLO\nWORLD", output.ToString());
    }

    [Fact]
    public void WrongNumberOfArgumentsThrowsUsage()
    {
        using var output = new StringWriter { NewLine = "\n" };

        foreach (string[] args in new string[][] { [], ["one", "two"] })
        {
            var exception = Assert.Throws<CommandException>(() => new UpperCommand().Run(args, output));
            Assert.Equal(ExitCodes.Usage, exception.ExitCode);
            Assert.Equal("usage: textkit upper <file>", exception.Message);
        }
        Assert.Equal("", output.ToString());
    }

    [Fact]
    public void RegistryContainsExactlyOneUpperCommand()
    {
        Assert.Single(CommandRegistry.All.OfType<UpperCommand>());
    }

    public void Dispose()
    {
        if (Directory.Exists(directory))
        {
            Directory.Delete(directory, recursive: true);
        }
    }
}

